// Written by js/build.shale from js/canvas/*.js; not checked in.
export const CANVAS_SAMPLES = [
  { title: "A bouncing ball", source: "// A bouncing ball\nlet x = 60, y = 80;\nlet dx = 4, dy = 3;\nconst r = 20;\n\nfunction frame(t) {\n  background(\"#f4efe6\");\n  noStroke();\n  fill(\"tomato\");\n  circle(x, y, r);\n  x += dx;\n  y += dy;\n  if (x < r || x > 400 - r) dx = -dx;\n  if (y < r || y > 400 - r) dy = -dy;\n}\n" },
  { title: "A turtle spiral: try it in slow motion", source: "// A turtle spiral: try it in slow motion\nbackground(\"white\");\nfor (let i = 0; i < 90; i++) {\n  stroke(`hsl(${i * 4}, 70%, 45%)`, 2);\n  forward(i * 2);\n  turn(89);\n}\nconsole.log(\"the turtle ends at heading\", (90 * 89) % 360);\n" },
  { title: "A clock whose second hand goes round once a minute", source: "// A clock whose second hand goes round once a minute\nfunction hand(angle, length, color, width) {\n  stroke(color, width);\n  line(200, 200, 200 + length * Math.sin(angle), 200 - length * Math.cos(angle));\n}\n\nfunction frame(t) {\n  background(\"#20242c\");\n  stroke(\"#d8d4cc\", 3);\n  fill(\"#2c323d\");\n  circle(200, 200, 170);\n  for (let i = 0; i < 60; i++) {\n    const a = (i / 60) * 2 * Math.PI;\n    const inner = i % 5 === 0 ? 148 : 158;\n    stroke(\"#d8d4cc\", i % 5 === 0 ? 3 : 1);\n    line(200 + inner * Math.sin(a), 200 - inner * Math.cos(a), 200 + 165 * Math.sin(a), 200 - 165 * Math.cos(a));\n  }\n  const seconds = t % 60;\n  hand((seconds / 3600) * 2 * Math.PI, 90, \"#d8d4cc\", 6);\n  hand((seconds / 60) * 2 * Math.PI, 150, \"tomato\", 2);\n  noStroke();\n  fill(\"tomato\");\n  circle(200, 200, 6);\n  fill(\"#d8d4cc\");\n  text(`${Math.floor(seconds)} s`, 180, 270, 20);\n}\n" },
  { title: "A starfield, flown through", source: "// A starfield, flown through\nlet seed = 42;\nfunction random() {\n  seed = (seed * 16807) % 2147483647;\n  return seed / 2147483647;\n}\n\nconst stars = [];\nfor (let i = 0; i < 80; i++) {\n  stars.push({ x: random() * 2 - 1, y: random() * 2 - 1, z: random() });\n}\n\nfunction frame(t) {\n  background(\"black\");\n  noStroke();\n  for (const s of stars) {\n    s.z -= 0.01;\n    if (s.z <= 0.02) {\n      s.z = 1;\n      s.x = random() * 2 - 1;\n      s.y = random() * 2 - 1;\n    }\n    const sx = 200 + (s.x / s.z) * 100;\n    const sy = 200 + (s.y / s.z) * 100;\n    const shade = Math.round(255 * (1 - s.z));\n    fill(`rgb(${shade}, ${shade}, ${shade})`);\n    circle(sx, sy, (1 - s.z) * 3);\n  }\n}\n" },
  { title: "A fractal tree, each branch two smaller ones", source: "// A fractal tree, each branch two smaller ones\nfunction branch(x, y, angle, length, depth) {\n  if (depth === 0) return;\n  const x2 = x + length * Math.sin(angle);\n  const y2 = y - length * Math.cos(angle);\n  stroke(depth > 3 ? \"#6b4226\" : \"#3a7d44\", depth);\n  line(x, y, x2, y2);\n  branch(x2, y2, angle - 0.42, length * 0.72, depth - 1);\n  branch(x2, y2, angle + 0.42, length * 0.72, depth - 1);\n}\n\nbackground(\"#eef4f8\");\nbranch(200, 390, 0, 95, 9);\n" },
  { title: "A tiny game: click the canvas, then steer with the arrow keys", source: "// A tiny game: click the canvas, then steer with the arrow keys\nlet seed = 7;\nfunction random(n) {\n  seed = (seed * 16807) % 2147483647;\n  return seed % n;\n}\n\nlet px = 200, py = 200;\nlet coinX = 40 + random(320), coinY = 40 + random(320);\nlet score = 0;\n\nfunction frame(t) {\n  if (keyIsDown(\"ArrowLeft\")) px -= 5;\n  if (keyIsDown(\"ArrowRight\")) px += 5;\n  if (keyIsDown(\"ArrowUp\")) py -= 5;\n  if (keyIsDown(\"ArrowDown\")) py += 5;\n  px = Math.max(10, Math.min(390, px));\n  py = Math.max(10, Math.min(390, py));\n  if (Math.abs(px - coinX) < 18 && Math.abs(py - coinY) < 18) {\n    score++;\n    console.log(\"coin\", score, \"at\", coinX, coinY);\n    coinX = 40 + random(320);\n    coinY = 40 + random(320);\n  }\n  background(\"#1d2433\");\n  noStroke();\n  fill(\"gold\");\n  circle(coinX, coinY, 9);\n  fill(\"#7fdbca\");\n  rect(px - 10, py - 10, 20, 20);\n  fill(\"white\");\n  text(`score ${score}`, 12, 28, 18);\n}\n" },
  { title: "Click to place dots", source: "// Click to place dots\n// Each click on the canvas adds a dot, joined to the last.\nlet dots = [];\nconst colors = [\"tomato\", \"gold\", \"#2a9d8f\", \"orchid\", \"#4a90d9\"];\n\nfunction draw() {\n  background(\"#f4efe6\");\n  stroke(\"#8a8178\", 2);\n  for (let i = 1; i < dots.length; i++) {\n    line(dots[i - 1][0], dots[i - 1][1], dots[i][0], dots[i][1]);\n  }\n  noStroke();\n  for (let i = 0; i < dots.length; i++) {\n    fill(colors[i % colors.length]);\n    circle(dots[i][0], dots[i][1], 12);\n  }\n  fill(\"#333\");\n  text(dots.length === 0 ? \"click the canvas\" : `${dots.length} dot${dots.length === 1 ? \"\" : \"s\"}`, 12, 28, 16);\n}\n\nonClick((x, y) => {\n  dots.push([Math.round(x), Math.round(y)]);\n  console.log(\"dot\", dots.length, \"at\", Math.round(x), Math.round(y));\n  draw();\n});\ndraw();\n" },
  { title: "A countdown on timers", source: "// A countdown on timers\n// setInterval ticks it down and a timeout rings after: no frame loop.\n// A click once it has rung starts it again.\nlet left = 0;\nlet counting = false;\n\nfunction show(words, color, size) {\n  background(color);\n  fill(\"white\");\n  text(words, 40, 220, size);\n}\n\nfunction countdown() {\n  counting = true;\n  left = 3;\n  show(`${left}...`, \"#3a6ea5\", 64);\n  const tick = setInterval(() => {\n    left--;\n    console.log(\"left\", left);\n    if (left > 0) {\n      show(`${left}...`, \"#3a6ea5\", 64);\n    } else {\n      clearInterval(tick);\n      show(\"go!\", \"#2e8b57\", 64);\n      setTimeout(() => {\n        show(\"click to go again\", \"#555\", 32);\n        counting = false;\n      }, 900);\n    }\n  }, 600);\n}\n\n// A click while it counts is ignored, so two intervals never run at once.\nonClick(() => {\n  if (!counting) countdown();\n});\ncountdown();\n" },
];
